;; curriculum: Algebra-1 (gr 9) — quadratic functions, symmetry; prerequisites: ramp
;; math target: y = x²/16 is a parabola; its vertex is the lowest point and the y-axis is its mirror.

app riya-level-valley "1.1.0"
"riya level 3 · The Valley — y = x² ⁄ 16 — the bars are the function, sampled. Drop into the valley and climb its walls — catch 5 ★! Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup, rendered through math-canvas so the axes and the world's own function stay visible. Rebound into the riya-game-platformer organism (menu + all eighteen worlds)."

;; @exposure internal

orbital RiyaValleyOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaValleyBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaValleyPlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaValleyFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaValleyStar = {
    id : string!
    x : number!
    y : number!
    type : string!
  }
  type RiyaValleyCurveSample = {
    x : number!
    y : number!
  }
  type RiyaValleyCurve = {
    label : string
    color : string
    samples : [RiyaValleyCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaValleyPadLock = {
    id : string!
    x : number!
    y : number!
    grp : number!
  }
  type RiyaValleyGuide = {
    kind : "vline" | "hline"!
    at : number!
    color : string
    dash : "dashed" | "dotted"
    label : string
  }
  type RiyaValleyPickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }
  type RiyaValleyLiftMod = {
    id : string!
    x0 : number!
    x1 : number!
    a : number!
    h : number!
    k : number!
  }
  type RiyaValleyFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }

  entity RiyaValleyState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaValleyBody = { x: 0, y: 0.4, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    features : [RiyaValleyStar] = []
    pickups : [RiyaValleyPickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaValleyFx] = []
    celebrated : boolean = false
    seq : number = 0
    lastText : string = ""
    zoneId : string = "valley"
    platforms : [RiyaValleyPlatform] = []
    curves : [RiyaValleyCurve] = []
  }

  entity ValleyTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }

  trait ValleyBody = Body.traits.PlatformerBody -> RiyaValleyState {
    events {
      STEER: VALLEY_STEER
      JUMP: VALLEY_LEAP
      PLACE: VALLEY_PLACE
      RESTART: VALLEY_RESTART
      CURVE_MOD_ADD: VALLEY_CURVE_MOD_ADD
      SET_PLATFORMS: VALLEY_SET_PLATFORMS
      SET_SKATE_CURVE: VALLEY_SET_SKATE_CURVE
      BODY_JUMPED: VALLEY_JUMPED
      BODY_LANDED: VALLEY_LANDED
      BODY_HAZARD: VALLEY_HAZARD
      BODY_GOAL: VALLEY_GOAL
      BODY_FELL: VALLEY_FELL
      BODY_SKATE_START: VALLEY_SKATE_ON
      BODY_SKATE_END: VALLEY_SKATE_OFF
    }
    config {
      running: true
      spawn: { x: 0, y: 0.4, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 9.4
      killY: -3
      skate: true
      curveModsEnabled: true
      skateSnap: 0.9
    }
  }

  trait ValleyGate = Gate.traits.ObjectiveFlow -> RiyaValleyState {
    events {
      PROGRESS: VALLEY_PROGRESS
      GAME_END: VALLEY_GAME_END
      RESTART: VALLEY_RESTART
    }
    config { running: true }
  }

  trait ValleyFx = Particles.traits.FxParticles -> RiyaValleyState {
    events {
      BURST: VALLEY_BURST
    }
    config { running: true }
  }

  trait ValleyTutorialPreview -> ValleyTutorialData [interaction, instance] {
    initial: idle
    state idle {
      INIT -> idle
        (render-ui center null)
    }
  }

  trait ValleyTutorial = Tutorial.traits.TutorialOverlay -> ValleyTutorialData {
    events {
      SHOW: VALLEY_TUTORIAL_SHOW
      TUTORIAL_DONE: VALLEY_TUTORIAL_DONE
    }
    config {
      autoShow: true
      previewTrait: @trait.ValleyTutorialPreview
      steps: [
        { id: "intro", title: "The Valley", body: "The bars are the graph y = x²/16. Skate the curve, collect ★, grab +k pads to lift the outer walls." }
      ]
    }
  }

  trait ValleyPickup = Pickup.traits.Pickup -> RiyaValleyState {
    events {
      PICKED: VALLEY_PICKED
      COLLECT: VALLEY_COLLECT
      PICKUP_SET_COMPLETED: VALLEY_PICKUP_SET_COMPLETED
      SET_FEATURES: VALLEY_SET_FEATURES
    }
    config {
      running: true
      reachX: 0.7
      reachY: 1.2
    }
  }

  trait ValleyLevelData -> @rebindable RiyaValleyState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "valley"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          skateCurve: (array/map @config.skateCurve (fn c @c))
          curveOverlay: (array/map @config.curveOverlay (fn c @c))
          guides: (array/map @config.guides (fn g @g))
          liftMods: (array/map @config.liftMods (fn m @m))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaValleyPlatform]!
        stars : [RiyaValleyPickup]!
        skateCurve : [RiyaValleyCurveSample]
        curveOverlay : [RiyaValleyCurve]
        guides : [RiyaValleyGuide]
        liftMods : [RiyaValleyLiftMod]
      }
        @description "The zone's canonical static geometry + pedagogy, broadcast once on INIT in zone-local coordinates. This atom's own play trait consumes it to seed the body/pickup authorities and the render; the riya open-world organism consumes the same event and applies its zone offset, so standalone and composed can never diverge."
        @tier "domain"
    }

    config {
      worldName : string = "The Valley"
        @label "World Name"
        @description "This world's display name — the open world's zone banner reads it from RIYA_LEVEL_DATA."
        @tier "presentation"
      equation : string = "y = x²/16"
        @label "Equation"
        @description "The zone's skate/banner equation."
        @tier "presentation"
      concept : string = "y = x²/16 is the terrain; symmetry about x = 0; +k lift pads translate the outer walls up so you can reach the high stars"
        @label "Concept"
        @description "The world's one math idea."
        @tier "presentation"
      regionColor : string = "#38bdf8"
        @label "Region Color"
        @description "Zone band accent in the open world."
        @tier "presentation"
      entryY : number = 3.06
        @label "Entry Y"
        @description "Run-surface height at the zone's left edge (top of tile v0: y −2 + height 5.06); the open world stitches its incoming bridge to this."
        @tier "domain"
      exitY : number = 3.06
        @label "Exit Y"
        @description "Run-surface height at the zone's right edge (top of tile v7: y −2 + height 5.06); the open world stitches its outgoing bridge to this."
        @tier "domain"
      platforms : [RiyaValleyPlatform] = [
        { id: "v0", x: -8, y: -2, width: 2, height: 5.06, type: "ground" }
        { id: "v1", x: -6, y: -2, width: 2, height: 3.56, type: "ground" }
        { id: "v2", x: -4, y: -2, width: 2, height: 2.56, type: "ground" }
        { id: "v3", x: -2, y: -2, width: 2, height: 2.06, type: "ground" }
        { id: "v4", x: 0, y: -2, width: 2, height: 2.06, type: "ground" }
        { id: "v5", x: 2, y: -2, width: 2, height: 2.56, type: "ground" }
        { id: "v6", x: 4, y: -2, width: 2, height: 3.56, type: "ground" }
        { id: "v7", x: 6, y: -2, width: 2, height: 5.06, type: "ground" }
      ]
        @label "Platforms"
        @description "Canonical terrain — seeds the body authority's collision AND the canvas bars via RIYA_LEVEL_DATA. Bar tops sample y = x²/16 at their centers."
        @tier "domain"
      stars : [RiyaValleyPickup] = [
        { id: "s1", x: 0, y: 1.3, kind: "star", glyph: "★", message: "" }
        { id: "s2", x: -5, y: 2.8, kind: "star", glyph: "★", message: "" }
