  trait ValleyChallenge -> @rebindable RiyaValleyState [game-core, instance] {
    initial: idle

    state idle {
      VALLEY_PICKED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (str/endsWith @payload.id "lift-l")
          (do
            (emit VALLEY_CURVE_MOD_ADD { x0: -8, x1: -5.5, a: 1, h: 0, k: 1.5 })
            (emit VALLEY_BURST { particles: (array/concat
              { id: "narrative-lift-l-fact", type: "narrative", x: -6, z: 5, y: 0, message: "f(x)+1.5", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 }
              { id: "narrative-lift-l-hint", type: "narrative", x: -6, z: 5.5, y: 0, message: "the wall rises", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
            ) }))
          (if (str/endsWith @payload.id "lift-r")
            (do
              (emit VALLEY_CURVE_MOD_ADD { x0: 5.5, x1: 8, a: 1, h: 0, k: 1.5 })
              (emit VALLEY_BURST { particles: (array/concat
                { id: "narrative-lift-r-fact", type: "narrative", x: 6, z: 5, y: 0, message: "f(x)+1.5", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 }
                { id: "narrative-lift-r-hint", type: "narrative", x: 6, z: 5.5, y: 0, message: "the wall rises", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
              ) }))
            null))
    }

    emits {
      VALLEY_CURVE_MOD_ADD -> external {
        x0 : number!
        x1 : number!
        a : number!
        h : number!
        k : number!
      }
        @description "Renamed CURVE_MOD_ADD consumed by the platformer-body authority; applies a lift/tilt mod to the skate curve."
        @tier "domain"
      VALLEY_BURST -> external {
        particles : [RiyaValleyFx]
      }
        @description "Particle batch spawned on a lift-pad pickup's narrative beats; fx-particles fades it."
        @tier "domain"
    }

    listens {
      VALLEY_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "valley"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
    }
  }

  trait RiyaValleyClear -> @rebindable RiyaValleyState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "VALLEY_NEXT", variant: "primary" } ]
        })

      VALLEY_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RIYA_LEVEL_SOLVED { level : string }
      VALLEY_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-valley"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to. Standalone default replays this world; riya-game-platformer overrides it with the next world's path."
        @tier "presentation"
      clearTitle : string = "Valley clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "A parabola is a valley you can walk — every bar's height is x²/16."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
    }
  }

  page "/riya-valley" as RiyaValleyPage -> ValleyLevelData, ValleyBody, ValleyGate, ValleyFx, ValleyPickup, ValleyTutorial, RiyaValleyGenre, RiyaValleyPlay, ValleyChallenge, RiyaValleyClear
}
